{
  "summary": "The reader has the standard undergraduate computer science core: discrete mathematics (Cartesian products, permutations, induction, binomial coefficients, graphs, modular arithmetic, gcd, primes and division with remainder), linear algebra over the real and rational numbers (vector spaces, bases, matrices, eigenvalues, dot products, Gaussian elimination), calculus-level analysis (logarithms, exponentials, limits, geometric sums, roots of unity and Euler's formula), and algorithms and computer organization (Omega, Theta and little-o notation, recurrences, positional notation, two's-complement words). Not assumed are fields other than F_2, tensor products, bilinear forms, Gaussian integers, rings and groups, the integer Chinese remainder theorem, limit inferior and Newton iteration.",
  "known": [
    {
      "name": "Omega, Theta and little-o notation",
      "aliases": ["Ω-notation", "Θ-notation", "o-notation", "little-o", "asymptotic lower bound", "asymptotic tight bound"],
      "gloss": "Ω(f(n)) is the set of functions bounded below by a positive constant times f(n) for all large n, Θ(f(n)) is the set of functions that are both O(f(n)) and Ω(f(n)), and o(f(n)) is the set of functions g(n) with g(n)/f(n) tending to 0."
    },
    {
      "name": "Logarithms and exponentials",
      "aliases": ["binary logarithm", "lg", "log base 2", "natural logarithm", "ln", "exp", "e^x"],
      "gloss": "The logarithm to base b is the inverse of the exponential b^x, satisfying log(xy) = log x + log y and log(x^c) = c log x, with lg denoting the base-2 logarithm and ln the natural logarithm."
    },
    {
      "name": "Floor and ceiling functions",
      "aliases": ["integer part", "floor", "ceiling", "round down", "round up"],
      "gloss": "The floor ⌊x⌋ is the largest integer not exceeding x, and the ceiling ⌈x⌉ is the smallest integer not less than x."
    },
    {
      "name": "Geometric series",
      "aliases": ["geometric sum", "finite geometric sum", "sum of powers of a ratio"],
      "gloss": "For a ratio r different from 1, the finite sum 1 + r + … + r^(k−1) equals (r^k − 1)/(r − 1)."
    },
    {
      "name": "Mathematical induction",
      "aliases": ["induction", "induction on n", "strong induction", "inductive proof"],
      "gloss": "Induction proves a statement for every integer n at least n0 by proving it for n0 and proving it for n from its truth for smaller values (strong induction) or for the previous value (weak induction)."
    },
    {
      "name": "Recurrence relations for running times",
      "aliases": ["recurrence", "recurrence equation", "unrolling a recurrence", "divide-and-conquer recurrence"],
      "gloss": "A recurrence defines a cost T(n) in terms of costs at smaller sizes, and is solved by unrolling it into a sum or by substituting a guessed bound and checking it by induction."
    },
    {
      "name": "Cartesian product of sets",
      "aliases": ["product set", "direct product", "ordered tuples of sets"],
      "gloss": "The Cartesian product A_1 × … × A_t is the set of ordered tuples (a_1, …, a_t) with each a_i in A_i."
    },
    {
      "name": "Permutation of a finite set",
      "aliases": ["bijection of a finite set", "rearrangement", "reordering", "address permutation"],
      "gloss": "A permutation of a finite set is a bijection from that set to itself, and permutations can be composed and inverted."
    },
    {
      "name": "Binomial coefficients",
      "aliases": ["n choose k", "C(n,k)", "combinations"],
      "gloss": "The binomial coefficient binom(n,k) counts the k-element subsets of an n-element set and equals n!/(k!(n−k)!)."
    },
    {
      "name": "Lexicographic order",
      "aliases": ["dictionary order", "lex order", "row-major order"],
      "gloss": "Tuples are ordered lexicographically by comparing their entries at the first position where they differ, so the row-major order of an array is the lexicographic order of its index pairs."
    },
    {
      "name": "Graphs, vertices and edges",
      "aliases": ["graph", "vertex", "edge", "adjacency", "neighbouring vertices", "intersection graph"],
      "gloss": "A graph consists of a set of vertices and a set of edges, each edge joining two vertices, and two vertices are adjacent when an edge joins them."
    },
    {
      "name": "Modular arithmetic and congruences",
      "aliases": ["congruence modulo m", "residue class", "residues mod m", "Z/mZ", "modular inverse", "arithmetic mod m"],
      "gloss": "a ≡ b (mod m) means that m divides a − b, arithmetic on residue classes modulo m is well defined, and a has an inverse modulo m exactly when gcd(a, m) = 1."
    },
    {
      "name": "Greatest common divisor and coprime integers",
      "aliases": ["gcd", "highest common factor", "relatively prime", "coprime", "Euclidean algorithm", "extended Euclidean algorithm"],
      "gloss": "The gcd of a and b is the largest integer dividing both, two integers are coprime when their gcd is 1, and the extended Euclidean algorithm finds integers x and y with ax + by = gcd(a, b)."
    },
    {
      "name": "Prime numbers",
      "aliases": ["primes", "primality", "trial division", "prime factorization"],
      "gloss": "A prime is an integer p at least 2 whose only positive divisors are 1 and p, and every integer at least 2 is a product of primes in exactly one way up to order."
    },
    {
      "name": "Division with remainder",
      "aliases": ["Euclidean division", "quotient and remainder", "integer division", "floor division"],
      "gloss": "For integers a and b > 0 there are unique integers q and r with a = bq + r and 0 ≤ r < b, and then q = ⌊a/b⌋."
    },
    {
      "name": "Limits of sequences and functions",
      "aliases": ["limit as n tends to infinity", "tends to zero", "convergence"],
      "gloss": "A quantity f(n) tends to L as n tends to infinity when, for every ε > 0, |f(n) − L| is less than ε for all sufficiently large n."
    },
    {
      "name": "Nth roots of unity and polar form",
      "aliases": ["roots of unity", "n-th roots of unity", "Euler's formula", "de Moivre's formula", "polar form", "unit circle"],
      "gloss": "The complex numbers z with z^n = 1 are e^(2πik/n) for k = 0, …, n−1, and Euler's formula e^(iθ) = cos θ + i sin θ gives every nonzero complex number the polar form r·e^(iθ)."
    },
    {
      "name": "Vector spaces, bases and linear maps",
      "aliases": ["linear space", "vector space over a field", "basis", "linear independence", "span", "linear transformation"],
      "gloss": "A vector space is a set closed under addition and scalar multiplication by a field of scalars, a basis is a linearly independent spanning set, and a linear map is a function between vector spaces that preserves addition and scalar multiplication."
    },
    {
      "name": "Matrices, inverses and triangular matrices",
      "aliases": ["matrix", "matrix product", "transpose", "identity matrix", "invertible matrix", "nonsingular matrix", "singular matrix", "lower-triangular matrix", "upper-triangular matrix"],
      "gloss": "A matrix records a linear map relative to chosen bases, matrix products correspond to composition of maps, an invertible matrix has an inverse, and a lower- or upper-triangular matrix has all entries on one side of the diagonal equal to zero."
    },
    {
      "name": "Eigenvalues and eigenvectors",
      "aliases": ["eigenvalue", "eigenvector", "spectrum"],
      "gloss": "A scalar λ is an eigenvalue of a square matrix M when Mv = λv for some nonzero vector v, and such a v is an eigenvector for λ."
    },
    {
      "name": "Gaussian elimination and elementary row operations",
      "aliases": ["row reduction", "elementary row operation", "elementary matrix", "row echelon form"],
      "gloss": "Gaussian elimination reduces a matrix by adding multiples of rows to other rows and swapping or scaling rows, and it writes an invertible matrix as a product of elementary matrices."
    },
    {
      "name": "Dot product and orthogonality",
      "aliases": ["inner product", "scalar product", "orthogonal vectors", "perpendicular vectors"],
      "gloss": "The dot product of x and y in R^n is the sum of the products x_i y_i, and two vectors are orthogonal when their dot product is zero."
    },
    {
      "name": "Indicator vector of a subset",
      "aliases": ["characteristic vector", "0-1 vector of a set", "indicator function"],
      "gloss": "For a subset T of a finite index set, its indicator vector has entry 1 at the positions of the elements of T and entry 0 at all other positions."
    },
    {
      "name": "Arithmetic modulo 2 and XOR",
      "aliases": ["exclusive or", "XOR", "parity", "F_2", "GF(2)", "field of two elements", "mod-2 arithmetic"],
      "gloss": "Addition of bits is the exclusive-or operation, so 1 + 1 = 0, and the integers modulo 2 form the field F_2 with two elements."
    },
    {
      "name": "Dyadic rational numbers",
      "aliases": ["dyadic rationals", "dyadic fractions", "binary fractions"],
      "gloss": "A dyadic rational is a number m/2^k with integers m and k, equivalently a rational number with a finite binary expansion."
    },
    {
      "name": "Positional (radix) notation",
      "aliases": ["base-b representation", "radix-b digits", "binary representation", "digit expansion"],
      "gloss": "A nonnegative integer n is written in base b as n = Σ d_j b^j with digits 0 ≤ d_j < b, and binary notation is the case b = 2."
    },
    {
      "name": "Two's-complement integers",
      "aliases": ["two's complement", "signed binary words", "signed fixed-width integers"],
      "gloss": "A w-bit two's-complement word represents the signed integers from −2^(w−1) to 2^(w−1) − 1, with its leading bit carrying weight −2^(w−1)."
    }
  ]
}
